import { z } from 'zod'
import { db, logAudit, OWNED_STORES, type OwnedStore } from './db'
import { SCHEMA_VERSION, VISIBILITIES, type Envelope } from '@/types/domain'

/**
 * Backup / restore (TRUST-02, blueprint 06 §9).
 *
 * A restore is the one place a hostile file reaches the database, so parsing is
 * strict and unforgiving: unknown schema version, bad envelope, or prototype
 * keys reject the whole package rather than importing "the good parts".
 */

export const BACKUP_FORMAT = 'temudua-backup'

const isoDate = z.string().min(4)

const envelopeSchema = z.object({
  id: z.string().min(1),
  schemaVersion: z.number().int().positive(),
  ownerProfileId: z.string().min(1),
  coOwnerProfileIds: z.array(z.string()),
  dataClass: z.string().min(1),
  visibility: z.enum(VISIBILITIES as unknown as [string, ...string[]]),
  approvalStatus: z.string().min(1),
  sharedWithProfileIds: z.array(z.string()),
  sharedUntil: isoDate.optional(),
  createdAt: isoDate,
  updatedAt: isoDate,
  deletedAt: isoDate.optional(),
  revokedAt: isoDate.optional(),
  version: z.number().int().nonnegative(),
})

/** Required body fields per store — enough to catch a truncated or wrong-shaped file. */
const REQUIRED_BODY: Record<OwnedStore, string[]> = {
  checkins: ['date', 'energy', 'connection'],
  needs: ['text'],
  appreciations: ['text'],
  topics: ['title', 'status'],
  repairs: ['message', 'status'],
  events: ['title', 'date', 'type'],
  tasks: ['title', 'accountableProfileId', 'mentalLoadType', 'status'],
  bills: ['title', 'amount', 'dueDate', 'payerProfileId', 'status', 'space'],
  memories: ['title', 'date'],
  cycles: ['startDate'],
  // Both v2 stores are discriminated unions; `kind` is the only field every
  // variant shares, so it is the only one worth asserting generically.
  wedding: ['kind'],
  family: ['kind'],
  groceries: ['name'],
  documents: ['name', 'docKind'],
  contacts: ['name', 'phone'],
  goals: ['title', 'targetAmount'],
  meetings: ['date'],
  // v4. `wishes` and `domains` are unions like the v2 stores, so `kind` is again
  // the only field every variant shares.
  wishes: ['kind'],
  domains: ['kind'],
  accounts: ['name', 'space', 'disclosure'],
  ledger: ['accountId', 'label', 'amount', 'date'],
  splits: ['label', 'amount', 'date', 'paidByProfileId', 'model'],
  contributionRules: ['model', 'effectiveFrom'],
  proposals: ['label', 'amount', 'tier', 'status'],
}

const profileSchema = z.object({
  id: z.string().min(1),
  displayName: z.string().min(1),
  stage: z.enum(['single', 'dating', 'married']),
  locale: z.enum(['id', 'en']),
  pinHash: z.string().optional(),
  pinSalt: z.string().optional(),
  createdAt: isoDate,
  stageHistory: z.array(z.object({ stage: z.string(), changedAt: isoDate })),
})

const packageSchema = z.object({
  format: z.literal(BACKUP_FORMAT),
  schemaVersion: z.number().int().positive(),
  exportedAt: isoDate,
  profiles: z.array(profileSchema),
  pairs: z.array(z.record(z.string(), z.unknown())),
  stores: z.record(z.string(), z.array(z.record(z.string(), z.unknown()))),
  audit: z.array(z.record(z.string(), z.unknown())),
  counts: z.record(z.string(), z.number()),
})

export type BackupPackage = z.infer<typeof packageSchema>

export interface ExportOptions {
  /** Owner performing the export. Only their readable data leaves the device. */
  actorProfileId: string
  /** Health (C4) and safety (C5) data stay behind unless explicitly opted in. */
  includeSensitive: boolean
}

export async function exportBackup(opts: ExportOptions): Promise<BackupPackage> {
  const stores: Record<string, unknown[]> = {}
  const counts: Record<string, number> = {}

  for (const store of OWNED_STORES) {
    const rows = (await db.table(store).toArray()) as Envelope[]
    const mine = rows.filter((r) => {
      if (r.ownerProfileId !== opts.actorProfileId && !r.coOwnerProfileIds.includes(opts.actorProfileId))
        return false
      if (!opts.includeSensitive && (r.dataClass === 'C4_health' || r.dataClass === 'C5_safety'))
        return false
      return true
    })
    stores[store] = mine
    counts[store] = mine.length
  }

  const pkg: BackupPackage = {
    format: BACKUP_FORMAT,
    schemaVersion: SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    profiles: await db.profiles.toArray(),
    pairs: (await db.pairs.toArray()) as unknown as Record<string, unknown>[],
    stores: stores as BackupPackage['stores'],
    audit: (await db.audit.toArray()) as unknown as Record<string, unknown>[],
    counts,
  }
  await logAudit({
    actorProfileId: opts.actorProfileId,
    action: 'export',
    objectStore: 'all',
    objectId: '-',
    summary: `export ${opts.includeSensitive ? 'termasuk' : 'tanpa'} data kesehatan`,
  })
  return pkg
}

export class RestoreError extends Error {}

/** Rejects `__proto__` / `constructor` keys anywhere in the tree. */
function assertNoPrototypePollution(value: unknown, path = 'root'): void {
  if (value === null || typeof value !== 'object') return
  if (Array.isArray(value)) {
    value.forEach((v, i) => assertNoPrototypePollution(v, `${path}[${i}]`))
    return
  }
  for (const key of Object.keys(value)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      throw new RestoreError(`File backup ditolak: ada isi yang tidak aman di ${path}.${key}`)
    }
    assertNoPrototypePollution((value as Record<string, unknown>)[key], `${path}.${key}`)
  }
}

/** Parses and validates without touching the database — used by the dry-run preview. */
export function parseBackup(raw: string): BackupPackage {
  let json: unknown
  try {
    json = JSON.parse(raw)
  } catch {
    throw new RestoreError('File ini bukan file TemuDua yang valid.')
  }
  assertNoPrototypePollution(json)

  const parsed = packageSchema.safeParse(json)
  if (!parsed.success) {
    throw new RestoreError('Isi file backup tidak cocok dengan format TemuDua.')
  }
  const pkg = parsed.data
  if (pkg.schemaVersion > SCHEMA_VERSION) {
    throw new RestoreError(
      `Backup ini dari versi TemuDua yang lebih baru (v${pkg.schemaVersion}). Update dulu aplikasinya.`,
    )
  }
  for (const [store, rows] of Object.entries(pkg.stores)) {
    if (!(OWNED_STORES as readonly string[]).includes(store)) {
      throw new RestoreError(`Backup berisi bagian yang tidak dikenal: ${store}.`)
    }
    const required = REQUIRED_BODY[store as OwnedStore]
    for (const row of rows) {
      if (!envelopeSchema.safeParse(row).success) {
        throw new RestoreError(`Ada catatan di ${store} yang rusak atau tidak lengkap.`)
      }
      for (const field of required) {
        if (row[field] === undefined) {
          throw new RestoreError(`Ada catatan di ${store} yang kehilangan isi "${field}".`)
        }
      }
    }
  }
  return pkg
}

export interface RestorePreview {
  exportedAt: string
  schemaVersion: number
  counts: Record<string, number>
  /** Records already present locally with the same id. */
  conflicts: number
  profiles: { id: string; displayName: string }[]
}

export async function previewRestore(pkg: BackupPackage): Promise<RestorePreview> {
  let conflicts = 0
  for (const [store, rows] of Object.entries(pkg.stores)) {
    for (const row of rows) {
      if (await db.table(store).get(row['id'] as string)) conflicts++
    }
  }
  return {
    exportedAt: pkg.exportedAt,
    schemaVersion: pkg.schemaVersion,
    counts: pkg.counts,
    conflicts,
    profiles: pkg.profiles.map((p) => ({ id: p.id, displayName: p.displayName })),
  }
}

export type RestoreMode = 'merge_keep_local' | 'merge_use_imported' | 'replace'

export async function restoreBackup(
  pkg: BackupPackage,
  mode: RestoreMode,
  actorProfileId: string,
): Promise<{ written: number; skipped: number }> {
  let written = 0
  let skipped = 0

  await db.transaction('rw', [db.profiles, db.pairs, db.audit, ...OWNED_STORES.map((s) => db.table(s))], async () => {
    if (mode === 'replace') {
      for (const store of OWNED_STORES) await db.table(store).clear()
    }
    for (const p of pkg.profiles) {
      const existing = await db.profiles.get(p.id)
      if (existing && mode === 'merge_keep_local') continue
      await db.profiles.put(p as never)
    }
    for (const [store, rows] of Object.entries(pkg.stores)) {
      for (const row of rows) {
        const id = row['id'] as string
        const existing = await db.table(store).get(id)
        if (existing && mode === 'merge_keep_local') {
          skipped++
          continue
        }
        await db.table(store).put(row)
        written++
      }
    }
  })

  await logAudit({
    actorProfileId,
    action: 'restore',
    objectStore: 'all',
    objectId: '-',
    summary: `restore ${mode}: ${written} tersimpan, ${skipped} dilewati`,
  })
  return { written, skipped }
}
